// Usage: node shot.mjs <mockup.html> <outprefix> [screens=deploy,server,domains,billing] [width=1440] [height=900]
// Wraps the artifact file in the same skeleton the Artifact host uses, opens each screen via location.hash,
// waits for preloader + reveal, and writes <outprefix>-<screen>.png (viewport) and <outprefix>-<screen>-full.png (full page).
import { createRequire } from 'node:module';
import fs from 'node:fs';
import path from 'node:path';
const require = createRequire('/opt/nxeon/node_modules/');
const { chromium } = require('playwright');

const [,, file, outprefix, screensArg = 'deploy,server,domains,billing', wArg = '1440', hArg = '900'] = process.argv;
if (!file || !outprefix) { console.error('usage: node shot.mjs <file.html> <outprefix> [screens] [w] [h]'); process.exit(1); }
const body = fs.readFileSync(file, 'utf8');
const html = `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>:root{color-scheme:light}body{margin:0;font:14px system-ui,sans-serif;background:#fafaf9}img{max-width:100%}[hidden]{display:none!important}</style></head><body>${body}</body></html>`;
const tmp = path.resolve(path.dirname(outprefix), path.basename(file) + '.wrapped.html');
fs.writeFileSync(tmp, html);
const browser = await chromium.launch();
const ctx = await browser.newContext({ viewport: { width: +wArg, height: +hArg }, deviceScaleFactor: 1, colorScheme: 'dark' });
const page = await ctx.newPage();
const errors = [];
page.on('pageerror', e => errors.push('pageerror: ' + e.message));
page.on('console', m => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
for (const s of screensArg.split(',')) {
  await page.goto('file://' + tmp + '#' + s, { waitUntil: 'load' });
  await page.waitForTimeout(3800);
  await page.screenshot({ path: `${outprefix}-${s}.png` });
  await page.screenshot({ path: `${outprefix}-${s}-full.png`, fullPage: true });
  const dims = await page.evaluate(() => ({ sw: document.documentElement.scrollWidth, cw: document.documentElement.clientWidth, sh: document.documentElement.scrollHeight }));
  console.log(`${s}: viewport ${wArg}x${hArg}, scrollWidth=${dims.sw} (client ${dims.cw}) scrollHeight=${dims.sh}${dims.sw > dims.cw ? '  <-- HORIZONTAL OVERFLOW' : ''}`);
}
await browser.close();
if (errors.length) { console.log('JS errors:\n' + errors.join('\n')); }
console.log('done');
